/** Query-string key for each `DeployIntent` field — see the file doc for why
 *  `service` keeps its pre-existing `product` name instead of a fresh one.
 *  Exported so order.tsx's `orderFromIntent` reads back the exact same keys
 *  this file writes, with no second list to keep in sync. */
export const DEPLOY_PARAM: { [K in keyof Required<DeployIntent>]: string } = {
  service: "product",
  planId: "plan",
  termMonths: "term",
  region: "region",
  addons: "addons",
  diskGb: "disk",
  gameFamily: "family",
  gamePlanId: "tier",
  gameVariant: "variant",
  players: "players",
  hostingPlanId: "hosting",
  emailPlanId: "email",
  couponCode: "coupon",
  subdomain: "sub",
  serverName: "name",
  hostname: "host",
};

/**
 * Builds `/dashboard/deploy?...` from whatever a Deploy click already knows.
 * Every field is optional — pass only what's actually selected; anything
 * omitted just leaves the wizard at its own sane default for that field.
 */
export function deployHref(intent: DeployIntent, base = "/dashboard/deploy"): string {
  const qs = new URLSearchParams();
  for (const key of Object.keys(DEPLOY_PARAM) as (keyof DeployIntent)[]) {
    const value = intent[key];
    if (value === undefined || value === null || value === "") continue;
    if (Array.isArray(value)) {
      if (value.length === 0) continue;
      qs.set(DEPLOY_PARAM[key], value.join(","));
    } else {
      qs.set(DEPLOY_PARAM[key], String(value));
    }
  }
  const s = qs.toString();
  return s ? `${base}?${s}` : base;
}

/** The slice of the wizard's `Order` the resume link reads (structural, so this file stays
 *  free of component imports and is unit-testable). */
export type ResumableOrder = {
  service: string | null; planId: string | null; termMonths: number; region: string | null; regionPicked?: boolean;
  hostname: string; addons: string[]; diskGb: number; gameFamily: string | null; gamePlanId: string | null;
  gameVariant: string | null; subdomain: string; serverName: string;
};

/** The tier the fast path (flag `growth_fast_path`) pre-selects when a link names a game but
 *  no tier: the MIDDLE of the price ladder — the same defensible, not-an-upsell rule the
 *  VPS "recommended" plan already uses (app/dashboard/deploy, `recommendedId`). It is a
 *  position in OUR ladder, not a popularity claim, and the wizard labels it exactly that. */
export function recommendedGameTierId(tiers: { id: string; monthlyCents: number; custom?: boolean }[]): string | null {
  const real = tiers.filter((t) => !t.custom).sort((a, b) => a.monthlyCents - b.monthlyCents);
  return real.length ? real[Math.floor((real.length - 1) / 2)].id : null;
}

/** The URL that resumes THIS draft at `/dashboard/deploy` after sign-up/login (mkt-011).
 *  Only non-secret selections travel; the price is never in the URL (re-quoted server-side). */
export function resumeHrefFromOrder(o: ResumableOrder, base = "/dashboard/deploy"): string {
  const qs = new URLSearchParams();
  const set = (k: keyof DeployIntent, v: string | number | undefined | null) => {
    if (v === undefined || v === null || v === "" || v === 0) return;
    qs.set(DEPLOY_PARAM[k], String(v));
  };
  if (o.service === "vps" || o.service === "game") set("service", o.service);
  set("termMonths", o.termMonths !== 1 ? o.termMonths : undefined);
  if (o.regionPicked) set("region", o.region);
  if (o.service === "vps") {
    set("planId", o.planId);
    set("diskGb", o.diskGb || undefined);
    if (o.addons.length) qs.set(DEPLOY_PARAM.addons, o.addons.join(","));
    set("hostname", o.hostname.trim());
  }
  if (o.service === "game") {
    set("gameFamily", o.gameFamily);
    set("gamePlanId", o.gamePlanId);
    set("gameVariant", o.gameVariant);
    set("subdomain", o.subdomain.trim());
    set("serverName", o.serverName.trim());
  }
  const s = qs.toString();
  return s ? `${base}?${s}` : base;
}

