/** Read the shared wallet balance for a linked Nxeon user. Body: { userId }. */
export async function POST(req: Request) {
  if (!(await isPartnerRequest(req))) return Response.json({ error: "unauthorized" }, { status: 401 });
  let body: { userId?: string };
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "invalid json" }, { status: 400 });
  }
  if (!body.userId) return Response.json({ error: "userId required" }, { status: 400 });
  const user = await db.user.findUnique({ where: { id: body.userId }, select: { balanceCents: true } });
  if (!user) return Response.json({ error: "user not found" }, { status: 404 });
  return Response.json({ balanceCents: user.balanceCents });
}
